import { useCallback, useMemo } from 'react';
import { useDispatch } from 'react-redux';

import { FilterForm, FilterValue, LoadFiltersParams } from 'models/Filters';
import { PERFORMANCE_TOOL_PAGE_NAME } from 'pages/pillars/ValueCreation/PerformanceTool/constants';
import {
  applyDirectValues,
  applyFilters,
  applyQuickFilters,
  bulkResetDraftFormFromDefaults,
  bulkResetQuickFiltersFormFromDefaults,
  dismissFilterAlertFallback,
  dismissPerformanceToolMarketShareTimePeriodFallback,
  dismissPerformanceToolTimePeriodFallback,
  loadFilters,
  resetAndApplyDefaults,
  restoreFilterAlertFallback,
  returnToPreviousMarketShareTimePeriod as returnToPreviousMarketShareTimePeriodAction,
  returnToPreviousPerformanceToolKpi,
  saveFilterAlertFallback,
  savePerformanceToolMarketShareTimePeriodFallback,
  savePerformanceToolTimePeriodFallback,
  setCurrentPage,
  setFormDraft,
  switchPerformanceToolKpi,
  updateFormValue,
  updateQuickFiltersFormValue,
} from 'redux/slices/filters';
import { AppDispatch } from 'redux/types';

export const usePageFilterManagement = (pageName: string | null) => {
  const dispatch = useDispatch<AppDispatch>();

  const setPage = useCallback(
    (name: string) => {
      dispatch(setCurrentPage(name));
    },
    [dispatch],
  );

  const loadPageFilters = useCallback(
    async (params: LoadFiltersParams) => {
      if (!pageName) return;
      return dispatch(loadFilters(params));
    },
    [dispatch, pageName],
  );

  const updateForm = useCallback(
    (key: string, value: FilterValue) => {
      if (!pageName) return;
      dispatch(updateFormValue({ key, value }));
    },
    [dispatch, pageName],
  );

  const updateQuickFiltersForm = useCallback(
    (key: string, value: FilterValue) => {
      if (!pageName) return;
      dispatch(updateQuickFiltersFormValue({ key, value }));
    },
    [dispatch, pageName],
  );

  const updateAllForm = useCallback(
    (form: FilterForm) => {
      if (!pageName) return;
      dispatch(setFormDraft(form));
    },
    [dispatch, pageName],
  );

  const updateAllQuickFiltersForm = useCallback(
    (quickForm: FilterForm, form: FilterForm) => {
      if (!pageName) return;
      dispatch(resetAndApplyDefaults({ form, quickForm }));
    },
    [dispatch, pageName],
  );

  const apply = useCallback(() => {
    if (!pageName) return;
    dispatch(applyFilters());
  }, [dispatch, pageName]);

  const applyQuickFiltersAction = useCallback(() => {
    if (!pageName) return;
    dispatch(applyQuickFilters());
  }, [dispatch, pageName]);

  const applyDirect = useCallback(
    (values: Partial<FilterForm>) => {
      if (!pageName) return;
      dispatch(applyDirectValues(values));
    },
    [dispatch, pageName],
  );

  const switchPerformanceToolKpiForPage = useCallback(
    (targetKpi: string, applyImmediately = false) => {
      if (!pageName) return;
      dispatch(switchPerformanceToolKpi({ targetKpi, applyImmediately }));
    },
    [dispatch, pageName],
  );
  const switchKpi =
    pageName === PERFORMANCE_TOOL_PAGE_NAME
      ? switchPerformanceToolKpiForPage
      : undefined;

  const dismissTimePeriodFallback = useCallback(() => {
    if (!pageName) return;
    dispatch(dismissPerformanceToolTimePeriodFallback());
  }, [dispatch, pageName]);

  const returnToPreviousKpi = useCallback(() => {
    if (!pageName) return;
    dispatch(returnToPreviousPerformanceToolKpi());
  }, [dispatch, pageName]);

  const returnToPreviousMarketShareTimePeriod = useCallback(() => {
    if (!pageName) return;
    dispatch(returnToPreviousMarketShareTimePeriodAction());
  }, [dispatch, pageName]);

  const saveTimePeriodFallback = useCallback(
    (
      previousFilters: FilterForm,
      targetKpi: string,
      reason?: 'kpi-switch' | 'time-period-unavailable',
    ) => {
      if (!pageName) return;
      dispatch(
        savePerformanceToolTimePeriodFallback({
          previousFilters,
          targetKpi,
          reason,
        }),
      );
    },
    [dispatch, pageName],
  );

  const saveMarketShareTimePeriodFallback = useCallback(
    (previousFilters: FilterForm, targetKpi: string) => {
      if (!pageName) return;
      dispatch(
        savePerformanceToolMarketShareTimePeriodFallback({
          previousFilters,
          targetKpi,
        }),
      );
    },
    [dispatch, pageName],
  );

  const dismissMarketShareTimePeriodFallback = useCallback(() => {
    if (!pageName) return;
    dispatch(dismissPerformanceToolMarketShareTimePeriodFallback());
  }, [dispatch, pageName]);

  const saveAlertFallback = useCallback(
    (payload: {
      key: string;
      previousFilters?: FilterForm;
      lastValidFilters?: FilterForm;
      targetFilters?: FilterForm;
      targetKpi?: string;
      restoreStrategy:
        'previous-filters' | 'last-valid-filters' | 'page-defaults';
    }) => {
      if (!pageName) return;
      dispatch(saveFilterAlertFallback({ pageName, ...payload }));
    },
    [dispatch, pageName],
  );

  const dismissAlertFallback = useCallback(
    (key: string) => {
      if (!pageName) return;
      dispatch(dismissFilterAlertFallback({ pageName, key }));
    },
    [dispatch, pageName],
  );

  const restoreAlertFallback = useCallback(
    (key: string) => {
      if (!pageName) return;
      dispatch(restoreFilterAlertFallback({ pageName, key }));
    },
    [dispatch, pageName],
  );

  const resetToDefaults = useCallback(
    (defaults: Record<string, FilterValue>) => {
      if (!pageName) return;
      dispatch(bulkResetDraftFormFromDefaults({ defaults }));
    },
    [dispatch, pageName],
  );

  const resetQuickFiltersToDefaults = useCallback(
    (defaults: Record<string, FilterValue>) => {
      if (!pageName) return;
      dispatch(bulkResetQuickFiltersFormFromDefaults({ defaults }));
    },
    [dispatch, pageName],
  );

  const resetToApplied = useCallback(
    (applied: Record<string, FilterValue>) => {
      if (!pageName) return;
      for (const [key, value] of Object.entries(applied)) {
        dispatch(updateFormValue({ key, value }));
      }
    },
    [dispatch, pageName],
  );

  return useMemo(
    () => ({
      setPage,
      loadPageFilters,
      updateForm,
      updateQuickFiltersForm,
      updateAllForm,
      updateAllQuickFiltersForm,
      apply,
      applyQuickFilters: applyQuickFiltersAction,
      applyDirect,
      switchKpi,
      dismissTimePeriodFallback,
      returnToPreviousKpi,
      dismissMarketShareTimePeriodFallback,
      returnToPreviousMarketShareTimePeriod,
      saveTimePeriodFallback,
      saveMarketShareTimePeriodFallback,
      saveAlertFallback,
      dismissAlertFallback,
      restoreAlertFallback,
      resetToDefaults,
      resetQuickFiltersToDefaults,
      resetToApplied,
    }),
    [
      setPage,
      loadPageFilters,
      updateForm,
      updateQuickFiltersForm,
      updateAllForm,
      updateAllQuickFiltersForm,
      apply,
      applyQuickFiltersAction,
      applyDirect,
      switchKpi,
      dismissTimePeriodFallback,
      returnToPreviousKpi,
      dismissMarketShareTimePeriodFallback,
      returnToPreviousMarketShareTimePeriod,
      saveTimePeriodFallback,
      saveMarketShareTimePeriodFallback,
      saveAlertFallback,
      dismissAlertFallback,
      restoreAlertFallback,
      resetToDefaults,
      resetQuickFiltersToDefaults,
      resetToApplied,
    ],
  );
};
